            current_time += pending;
            pending = 1;

            if (type == 'R') {
                seen[x] = 1;
                recv_time[x] = current_time;
            } else if (type == 'E') {
                seen[x] = 1;
                if (recv_time[x] != -1) {
                    total[x] += current_time - recv_time[x];
                    recv_time[x] = -1;
                }
            }
        }
    }

    for (int i = 1; i <= 100; i++) {
        if (seen[i]) {
            if (recv_time[i] != -1) {
                total[i] = -1;
            }
            printf("%d %d\n", i, total[i]);
        }
    }

    return 0;
}
